import React, { useEffect, useState } from "react";
import { ReactComponent as ArrowUpDown } from "../../assets/sidebar/arrow_up_down.svg";
import { ReactComponent as DeleteIcon } from "../../assets/products/sub_categories/delete_icon.svg";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { apisPath, paths } from "../../utils/path";
import { useLocation, useNavigate } from "react-router-dom";
import http from "../../services/utility";
import { useDispatch } from "react-redux";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";

export default function ComboProductList() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { state } = useLocation();
  const [comboId, setComboId] = useState(state?.comboId);
  const [comboName, setComboName] = useState(state?.comboName);
  const [comboData, setComboData] = useState(state?.comboData);
  const [cardData, setCardData] = useState([]);

  const [addedProductHeader, setAddedProductHeader] = useState([
    { name: "Product" },
    { name: "Price" },
    { name: "Expiry date" },
    { name: "Action" },
  ]);

  const [allProductList, setAllProductList] = useState([]);
  const [addedProduct, setAddedProduct] = useState([]);
  const [addedProductIds, setAddedProductIds] = useState([]);

  const [comboSubCatId, setComboSubCatId] = useState("");

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    let comboData;
    await http
      .get(`${apisPath?.admin?.comboProducts}?catId=${comboId}`)
      .then(async (res) => {
        // console.log(res?.data?.combo);
        comboData = res?.data?.combo;
        setCardData(res?.data?.combo);
      })
      .catch((err) => {
        console.log(err);
      });

    await http
      .get(apisPath?.admin?.productAllData)
      .then(async (res) => {
        // console.log(res?.data?.products);
        let data = res?.data?.products?.filter(
          (product) => !comboData.some((combo) => combo?.id === product?.id)
        );
        let data1 = comboData?.map((item) => item?.id);
        setAddedProductIds(data1);
        setAllProductList(data);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const deleteData = async () => {
    await http
      .delete(`${apisPath?.admin?.comboCategories}/${comboId}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );

        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const addNewProducts = async () => {
    await http
      .post(`${apisPath?.admin?.comboProducts}`, {
        catId: comboId,
        products: addedProductIds,
      })
      .then(async (res) => {
        // console.log(res?.data?.deal);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        setComboSubCatId("");
        setAddedProductIds([]);
        setAddedProduct([]);
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const changeSubCat = (index) => {
    setComboSubCatId(index);
  };

  return (
    <div className="sub_categories">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Combo product list</h3>
      </div>
      <div className="sub_categories__content">
        <div className="sub_categories__content__sub_categories_list">
          <h4 className="sub_categories__heading page_subheading">
            {comboName}
            {/* <button
              className="button-red"
              onClick={() =>
                navigate(
                  `/${paths?.front?.user?.combo}/${paths?.front?.user?.add_combo_sub_category}`,
                  {
                    state: { data: [], addSubCat: true, comboId: comboId },
                  }
                )
              }
            >
              Add combo category
            </button> */}
          </h4>
          <div className="sub_categories__content__sub_categories_list__content">
            {comboData?.map((data, index) => {
              return (
                <BrandCard
                  key={index}
                  data={data}
                  deleteData={deleteData}
                  comboId={comboId}
                  getData={getData}
                  productData={cardData}
                  changeSubCat={() => {
                    if (comboSubCatId == "") {
                      changeSubCat(data?.id);
                    } else {
                      setComboSubCatId("");
                    }
                  }}
                />
              );
            })}
          </div>
        </div>
        {comboSubCatId !== "" && (
          <div className="sub_categories__content__add_product">
            <div className="sub_categories__content__add_product__added_product">
              <h4 className="sub_categories__content__add_product__added_product__heading page_subheading">
                Added product
              </h4>
              <div className="sub_categories__content__add_product__added_product__content">
                <table className="deals__content__card_container__table__table">
                  <tr>
                    {addedProductHeader?.map((header, index) => {
                      return (
                        <th key={index}>
                          <span>
                            {header?.name} <ArrowDropDownIcon />
                          </span>
                        </th>
                      );
                    })}
                  </tr>
                  {addedProduct?.map((data, index) => {
                    return (
                      <tr key={index}>
                        <td>
                          <div className="product div-flex">
                            <img src={data?.images[0]} alt="Product Image" />
                            <div className="product__info">
                              <span>{data?.name}</span>
                              <span>
                                Details:{" "}
                                {data?.details?.length > 0
                                  ? data?.details[0]?.body
                                  : ""}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td>&#8377; {data?.price}</td>
                        {/* <td>{data?.purchased}</td>
                        <td>{data?.stock}</td> */}
                        <td>
                          {new Date(data?.createdAt)?.toLocaleString("en-US", {
                            weekday: "short",
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                            timeZone: "UTC",
                          })}
                        </td>
                        <td>
                          <div className="product_action">
                            <button
                              className="button-red"
                              onClick={() => {
                                const updatedArray = addedProduct?.filter(
                                  (item) => item.id !== data?.id
                                );
                                setAddedProduct(updatedArray);
                              }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </table>
              </div>
              <button className="button-red" onClick={addNewProducts}>
                Add Products
              </button>
            </div>

            <div className="sub_categories__content__add_product__all_product">
              <h4 className="sub_categories__content__add_product__all_product__heading page_subheading">
                All product list
              </h4>

              <div className="sub_categories__content__add_product__all_product__content">
                <table className="deals__content__card_container__table__table">
                  <tr>
                    {addedProductHeader?.map((header, index) => {
                      return (
                        <th key={index}>
                          <span>
                            {header?.name} <ArrowDropDownIcon />
                          </span>
                        </th>
                      );
                    })}
                  </tr>
                  {allProductList?.map((data, index) => {
                    return (
                      <tr key={index}>
                        <td>
                          <div className="product div-flex">
                            <img src={data?.images[0]} alt="Product Image" />
                            <div className="product__info">
                              <span>{data?.name}</span>
                              <span>
                                Details:{" "}
                                {data?.details?.length > 0
                                  ? data?.details[0]?.body
                                  : ""}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td>&#8377; {data?.price}</td>
                        {/* <td>{data?.purchased}</td>
                        <td>{data?.stock}</td> */}
                        <td>
                          {new Date(data?.createdAt)?.toLocaleString("en-US", {
                            weekday: "short",
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                            timeZone: "UTC",
                          })}
                        </td>
                        <td>
                          <div className="product_action">
                            <button
                              className="button-red"
                              onClick={() => {
                                const updatedArray = allProductList?.filter(
                                  (item) => item.id !== data?.id
                                );
                                setAllProductList(updatedArray);

                                setAddedProduct((prev) => {
                                  return [...prev, data];
                                });

                                setAddedProductIds((prev) => {
                                  return [...prev, data?.id];
                                });
                              }}
                            >
                              Add
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const BrandCard = ({
  data,
  deleteData,
  productData,
  comboId,
  getData,
  changeSubCat,
}) => {
  const dispatch = useDispatch();

  const triggerDropdown = (e) => {
    const ul = e?.currentTarget?.nextSibling;
    ul?.classList?.toggle("display-block");
  };

  const deleteProduct = async (index) => {
    await http
      .delete(`${apisPath?.admin?.comboProducts}/${comboId}/${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <div className="sub_categories_list_card">
      <div className="sub_categories_list_card__content">
        <img src={data?.image} alt={data?.name} />
      </div>

      <div className="sub_categories_list_card__select">
        <div
          className="sub_categories_list_card__select__dropdown"
          onClick={triggerDropdown}
          style={{
            cursor: productData?.length === 0 ? "context-menu" : "pointer",
          }}
        >
          <span>Product List</span>
          <ArrowUpDown />
        </div>

        {productData?.length > 0 && (
          <ul>
            {productData?.map((item, index) => {
              return (
                <li key={index}>
                  <span>{item?.name}</span>
                  <DeleteIcon onClick={() => deleteProduct(item?.id)} />
                </li>
              );
            })}
          </ul>
        )}
      </div>

      <button className="button-red" onClick={changeSubCat}>
        Add product
      </button>
      <button className="button-red" onClick={deleteData}>
        Delete
      </button>
    </div>
  );
};
